-- Xunjia Agent / OceanBase CE (MySQL-compatible tenant) business schema
-- Deterministically generated by scripts/export_oceanbase_schema.py.
-- AUTHORITATIVE SOURCE: server/schema.py -> statements(mysql=True)
--
-- DBA PRECONDITIONS:
--   1. Provision and explicitly select a dedicated xunjia_* database.
--   2. Verify SELECT VERSION() identifies OceanBase and
--      SHOW VARIABLES LIKE 'ob_compatibility_mode' returns MYSQL.
--   3. Approve this DDL and the application's minimal table/index privileges.
--
-- This file intentionally contains no CREATE DATABASE / DROP / USE / GRANT,
-- passwords, connection settings, or customer data. It only creates the
-- Current V2.2 application tables and their original inline indexes.
-- CREATE TABLE IF NOT EXISTS supports a first install. It does NOT migrate
-- existing schema revisions or validate columns on pre-existing tables.
-- Use a reviewed migration plan for upgrades; never silently overwrite.

CREATE TABLE IF NOT EXISTS xj2_owner (
        owner_id VARCHAR(160) PRIMARY KEY, control_version BIGINT NOT NULL,
        send_allowed INTEGER NOT NULL, projection_version BIGINT NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE IF NOT EXISTS xj2_group (
        group_id VARCHAR(64) PRIMARY KEY, owner_id VARCHAR(160) NOT NULL,
        bond_code VARCHAR(32) NOT NULL, our_side VARCHAR(8) NOT NULL,
        target_volume VARCHAR(48) NOT NULL, trade_day VARCHAR(10) NOT NULL,
        policy_json LONGTEXT NOT NULL, boundary_json LONGTEXT NOT NULL,
        valuation_json LONGTEXT NOT NULL, version BIGINT NOT NULL,
        policy_version BIGINT NOT NULL, control_version BIGINT NOT NULL,
        send_allowed INTEGER NOT NULL, state VARCHAR(32) NOT NULL,
        review_needed INTEGER NOT NULL, handoff_json LONGTEXT NOT NULL,
        plan_json LONGTEXT NOT NULL DEFAULT '{}', archived INTEGER NOT NULL DEFAULT 0,
        created_at DOUBLE NOT NULL DEFAULT 0, KEY idx_xj2_owner (owner_id,bond_code)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE IF NOT EXISTS xj2_thread (
        thread_id VARCHAR(64) PRIMARY KEY, owner_id VARCHAR(160) NOT NULL,
        account_uid VARCHAR(80) NOT NULL, peer_uid VARCHAR(160) NOT NULL,
        ingest_revision BIGINT NOT NULL, analyzed_revision BIGINT NOT NULL,
        pending_since DOUBLE, last_ingest_at DOUBLE,
        source_watermark BIGINT NOT NULL DEFAULT 0, dispatch_version BIGINT NOT NULL DEFAULT 0,
        receiver_fence_id VARCHAR(160), receiver_fence_version BIGINT NOT NULL DEFAULT 0,
        UNIQUE(owner_id,account_uid,peer_uid)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE IF NOT EXISTS xj2_peer (
        member_id VARCHAR(64) PRIMARY KEY, group_id VARCHAR(64) NOT NULL,
        thread_id VARCHAR(64) NOT NULL, version BIGINT NOT NULL,
        control_version BIGINT NOT NULL, send_allowed INTEGER NOT NULL,
        pending_command_id VARCHAR(64), waiting_command_id VARCHAR(64),
        waiting_since DOUBLE, response_state VARCHAR(24) NOT NULL,
        reconfirm_day VARCHAR(10), reconfirm_command_id VARCHAR(64),
        our_quote_json LONGTEXT NOT NULL, UNIQUE(group_id,thread_id), KEY idx_xj2_peer_thread (thread_id,group_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE IF NOT EXISTS xj2_message (
        message_id VARCHAR(64) PRIMARY KEY, thread_id VARCHAR(64) NOT NULL,
        event_id VARCHAR(160) NOT NULL, content_hash VARCHAR(64) NOT NULL,
        source_seq BIGINT NOT NULL, ingest_revision BIGINT NOT NULL,
        direction VARCHAR(8) NOT NULL, kind VARCHAR(16) NOT NULL,
        text LONGTEXT NOT NULL, native_id VARCHAR(160), target_id VARCHAR(64),
        occurred_at DOUBLE NOT NULL, received_at DOUBLE NOT NULL,
        trade_day VARCHAR(10) NOT NULL,
        historical INTEGER NOT NULL, UNIQUE(thread_id,event_id),
        UNIQUE(thread_id,ingest_revision), KEY idx_xj2_message_order (thread_id,source_seq,message_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE IF NOT EXISTS xj2_scope (
        message_id VARCHAR(64) NOT NULL, member_id VARCHAR(64) NOT NULL,
        relation VARCHAR(24) NOT NULL, PRIMARY KEY(message_id,member_id), KEY idx_xj2_scope_member (member_id,message_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE IF NOT EXISTS xj2_quote (
        quote_id VARCHAR(64) PRIMARY KEY, member_id VARCHAR(64) NOT NULL,
        side VARCHAR(8) NOT NULL, revision BIGINT NOT NULL,
        analysis_id VARCHAR(64) NOT NULL, state_json LONGTEXT NOT NULL,
        created_at DOUBLE NOT NULL, UNIQUE(member_id,side,revision), KEY idx_xj2_quote_current (member_id,side,revision)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE IF NOT EXISTS xj2_analysis (
        analysis_id VARCHAR(64) PRIMARY KEY, thread_id VARCHAR(64) NOT NULL,
        from_revision BIGINT NOT NULL, through_revision BIGINT NOT NULL,
        state VARCHAR(24) NOT NULL, lease_token VARCHAR(64) NOT NULL,
        lease_until DOUBLE NOT NULL, attempts BIGINT NOT NULL,
        snapshot_json LONGTEXT NOT NULL, result_json LONGTEXT NOT NULL,
        created_at DOUBLE NOT NULL, committed_at DOUBLE,
        UNIQUE(thread_id,through_revision), KEY idx_xj2_analysis_work (thread_id,state,lease_until)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE IF NOT EXISTS xj2_command (
        command_id VARCHAR(64) PRIMARY KEY, request_id VARCHAR(160) NOT NULL,
        member_id VARCHAR(64) NOT NULL, group_id VARCHAR(64) NOT NULL,
        thread_id VARCHAR(64) NOT NULL, state VARCHAR(24) NOT NULL,
        content_hash VARCHAR(64) NOT NULL, body_json LONGTEXT NOT NULL,
        basis_json LONGTEXT NOT NULL, result_json LONGTEXT NOT NULL,
        cancel_requested INTEGER NOT NULL, sent_at DOUBLE, native_id VARCHAR(160),
        created_at DOUBLE NOT NULL, expires_at DOUBLE NOT NULL,
        UNIQUE(member_id,request_id), KEY idx_xj2_cmd_pending (thread_id,state,created_at), KEY idx_xj2_cmd_group (group_id,state)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE IF NOT EXISTS xj2_decision (
        decision_id VARCHAR(64) PRIMARY KEY, member_id VARCHAR(64) NOT NULL,
        basis_json LONGTEXT NOT NULL, state VARCHAR(24) NOT NULL,
        result_json LONGTEXT NOT NULL, created_at DOUBLE NOT NULL,
        command_id VARCHAR(64), KEY idx_xj2_decision_member (member_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE IF NOT EXISTS xj2_binding (
        owner_id VARCHAR(160) PRIMARY KEY, account_uid VARCHAR(80) NOT NULL UNIQUE,
        workbench_id VARCHAR(160) NOT NULL, transport VARCHAR(8) NOT NULL,
        version BIGINT NOT NULL, config_json LONGTEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE IF NOT EXISTS xj2_batch (
        batch_id VARCHAR(64) PRIMARY KEY, owner_id VARCHAR(160) NOT NULL,
        request_id VARCHAR(160) NOT NULL, content_hash VARCHAR(64) NOT NULL,
        version BIGINT NOT NULL, state VARCHAR(24) NOT NULL, binding_version BIGINT NOT NULL,
        preview_json LONGTEXT NOT NULL, result_json LONGTEXT NOT NULL,
        created_at DOUBLE NOT NULL, UNIQUE(owner_id,request_id), KEY idx_xj2_batch_owner (owner_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE IF NOT EXISTS xj2_audit (
        audit_id VARCHAR(64) PRIMARY KEY, owner_id VARCHAR(160) NOT NULL,
        kind VARCHAR(64) NOT NULL, entity_id VARCHAR(160) NOT NULL,
        created_at DOUBLE NOT NULL, data_json LONGTEXT NOT NULL, KEY idx_xj2_audit_owner (owner_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE IF NOT EXISTS xj2_command_member (
        command_id VARCHAR(64) NOT NULL, member_id VARCHAR(64) NOT NULL,
        PRIMARY KEY(command_id,member_id), KEY idx_xj2_command_member (member_id,command_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE IF NOT EXISTS xj2_reply_job (
        job_id VARCHAR(64) PRIMARY KEY, member_id VARCHAR(64) NOT NULL,
        request_id VARCHAR(160) NOT NULL, basis_json LONGTEXT NOT NULL,
        state VARCHAR(24) NOT NULL, lease_token VARCHAR(64) NOT NULL,
        lease_until DOUBLE NOT NULL, attempts BIGINT NOT NULL,
        result_json LONGTEXT NOT NULL, created_at DOUBLE NOT NULL,
        UNIQUE(member_id,request_id), KEY idx_xj2_reply_job (state,lease_until)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
